WITH matched_keys AS (SELECT method, order_id FROM payments EXCEPT SELECT method, order_id FROM payments WHERE paid_at < '2025-05-01'), kept_rows AS (SELECT s.* FROM payments s JOIN matched_keys k ON s.method = k.method AND s.order_id = k.order_id) SELECT order_id, method, amount, paid_at, CASE WHEN method RLIKE '^(promptpay|cash)$' THEN 'CORE' ELSE 'EXTENDED' END AS method_zone FROM kept_rows;
